-- Additive operations entities; transactional migration, existing history remains untouched.
-- Roll back application while retaining these unused tables; do not drop financial evidence.
CREATE TABLE policies (id TEXT PRIMARY KEY, owner TEXT, outlet TEXT, status TEXT NOT NULL, month TEXT, version INTEGER, current INTEGER NOT NULL DEFAULT 0, amount_cents INTEGER, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE INDEX idx_policies_owner_status ON policies(owner,status);
CREATE INDEX idx_policies_outlet_month ON policies(outlet,month);
CREATE TABLE pricePlans (id TEXT PRIMARY KEY, owner TEXT, outlet TEXT, status TEXT NOT NULL, month TEXT, version INTEGER, current INTEGER NOT NULL DEFAULT 0, amount_cents INTEGER, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
