CREATE UNIQUE INDEX idx_offline_reference ON offlinePayments(json_extract(data,'$.reference'));
CREATE UNIQUE INDEX idx_refund_reference ON refundRequests(json_extract(data,'$.reference')) WHERE json_extract(data,'$.reference') IS NOT NULL;
CREATE UNIQUE INDEX idx_invoice_number ON invoiceRequests(json_extract(data,'$.number')) WHERE json_extract(data,'$.number') IS NOT NULL;
CREATE UNIQUE INDEX idx_job_key ON jobRuns(json_extract(data,'$.jobKey'));

